 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 640;
    frame.Height = 400;
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    // gAcptNo = frame.Provider("../").gAcptNo;
    // gMainFormCd = frame.Provider("../").gMainFormCd;
    // gFormVer = frame.Provider("../").gFormVer;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // alert("회사코드:"+gIsurCd);

};

/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd"));

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

