클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    await scwin.search();
};

/**
 * @method
 * @name search
 * @description 화면 로딩시 디폴트 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_DsclAcptListAll",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclAcptListAll=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclAcptListAll.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclAcptListAll.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclAcptListAll.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclAcptListAll.getCellData(Number(obj), "ISUR_CD");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name openDisclViewerMIS
 * @description open Discl Viewer MIS 처리
 * @param {*} pAcptNo pAcptNo
 * @param {*} pViewerStat pViewerStat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDisclViewerMIS = async function(pAcptNo, pViewerStat) {
    const url = "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&screnID=" + 'ULDSTF30204.xml';
    const winTitle = "공시뷰어";
    await $c.frame.CreateDialogFrame("viewer" + pAcptNo, url, winTitle, -200, -300, 1000, 800, "window”");
};

/**
 * @method
 * @name grd_DsclAcptListAll_OnClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_DsclAcptListAll_OnClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "PROCS_DATE") {
        // 부모창에 셋팅하기
        $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
        $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "PROCS_DATE"));
        $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
        // self.close();
        await $c.win.closePopup();
    }
};

/**
 * @method
 * @name grd_DsclAcptListAll_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_DsclAcptListAll_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    const result = "";
    if (colid === "DOC_TITLE") {
        /*
        var url = "/dsclproc/ULDSTF10001.gfm";
        var winTitle ="임시제목  - (회사명/보고서명/접수날짜)";
        frame.CreateDialogFrame("gform", url , winTitle ,100, 10, 1000, 800, "window" );
        //frame.CreateFrame("viewer", url , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);
         */
        // fn_OpenDisclViewer(gAcptNo,'R');

        await scwin.openDisclViewerMIS(scwin.gAcptNo, 'R');
    } else if (colid === "ACPT_DATE") {
        // 부모창에 셋팅하기
        $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
        $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_DATE"));
        $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
        // self.close();
        await $c.win.closePopup();
    }
};

/**
 * @method
 * @name dts_DsclAcptListAll_OnLoadError
 * @description dts_DsclAcptListAll 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclAcptListAll_OnLoadError = async function() {
    await $c.win.alert(dts_DsclAcptListAll);
};

/**
 * @method
 * @name dts_DsclAcptListAll_OnLoadCompleted
 * @description dts_DsclAcptListAll 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclAcptListAll_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclAcptListAll.errorMsg) {
        await $c.win.alert(dts_DsclAcptListAll.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    // self.close();
    await $c.win.closePopup();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF30204.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_DsclAcptListAll, {fileName: "제출보고서 목록", type: "2"});
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    scwin.getParentValue();
    scwin.resizeToWin();
    scwin.setCode();
    // fn_getParam();

    // 가우스헤더 셋팅
    // dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
    // dts_StudyCond.reset();

    await scwin.search();
};
